#!/usr/bin/env bash
# ============================================================================
# VideoMind rebuild, Part 3b: video details, who can watch, library pages
# ============================================================================
# FOR THE rebuild BRANCH ONLY. It refuses to run on main.
#
# Until now a video had a title and a description, anyone who had its
# address could open it, and the library was one flat list.
#
# After this part:
#   * the upload form asks for category, collection, tags and who can
#     watch, next to title and description
#   * who can watch: Private (only the owner, signed in), Unlisted
#     (anyone who has the link) or Public. A new upload is Private until
#     its owner chooses otherwise. Videos uploaded before this part
#     become Unlisted, which is how they have behaved so far
#   * private is enforced on the server: the video, its status, its
#     steps and Ask all answer "private" to anyone but the owner, and
#     the playback address is only given to the owner
#   * a private video is not sent to Shelby by itself, because a file on
#     Shelby can be read by anyone who has its address. The owner can
#     still choose to store it there
#   * Edit details on the video page changes any of it later
#   * the sidebar pages work: Courses lists collections, and Lectures,
#     Seminars, Presentations, Events and Live recordings list videos
#     by category
#   * All videos can be narrowed by category and by a word in a title
#     or tag
#   * the library query reads only the caller's own rows. Before, it
#     read the Shelby and AI rows of every video in the database
#
#   BACKEND   2 new files, 8 changed. Database migration 005_video_info
#             runs by itself at startup. No new packages.
#   FRONTEND  7 new files, 7 changed. No new packages.
#
#   ./vm_info.sh            apply (needs Part 3a on the branch)
#   ./vm_info.sh --force    apply even if local files differ from GitHub
#   ./vm_info.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_info"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_info_backups"

ADD=(
  "backend/src/lib/videoInfo.ts"
  "backend/src/routes/collections.ts"
  "frontend/src/lib/categories.ts"
  "frontend/src/components/video/VideoInfoForm.tsx"
  "frontend/src/components/video/VideoDetails.tsx"
  "frontend/src/components/library/LibraryView.tsx"
  "frontend/src/app/library/[view]/page.tsx"
  "frontend/src/app/library/courses/page.tsx"
  "frontend/src/app/library/courses/[id]/page.tsx"
)
MOD=(
  "backend/src/index.ts"
  "backend/src/lib/migrations.ts"
  "backend/src/lib/store.ts"
  "backend/src/lib/uploads.ts"
  "backend/src/routes/chat.ts"
  "backend/src/routes/uploads.ts"
  "backend/src/routes/videos.ts"
  "backend/src/types/video.ts"
  "frontend/src/app/library/page.tsx"
  "frontend/src/app/v/[id]/page.tsx"
  "frontend/src/app/video/[id]/page.tsx"
  "frontend/src/components/layout/AppShell.tsx"
  "frontend/src/components/upload/UploadZone.tsx"
  "frontend/src/components/video/VideoCard.tsx"
  "frontend/src/lib/api.ts"
)
