grep -q "$MARKER" "$TMPD/a0"                       || die "videoInfo.ts payload missing marker. Aborting."
grep -q "$MARKER" "$TMPD/a5"                       || die "LibraryView.tsx payload missing marker. Aborting."
grep -q '005_video_info' "$TMPD/m1"              || die "migrations.ts payload missing migration 005. Aborting."
grep -q '004_uploads' "$TMPD/m1"                 || die "migrations.ts payload lost migration 004. Aborting."
grep -q '/api/collections' "$TMPD/m0"            || die "index.ts payload does not mount the collection routes. Aborting."
grep -q '/api/uploads' "$TMPD/m0"                || die "index.ts payload lost the upload routes. Aborting."
grep -q 'canView' "$TMPD/m6"                     || die "videos.ts payload has no private check. Aborting."
grep -q 'canView' "$TMPD/m4"                     || die "chat.ts payload has no private check. Aborting."
grep -q 'requireAuth' "$TMPD/m6"                 || die "videos.ts payload lost sign in. Aborting."
grep -q 'requireAuth' "$TMPD/a1"                   || die "routes/collections.ts payload has no sign in check. Aborting."
grep -q 'ResumableUpload' "$TMPD/m12"            || die "UploadZone.tsx payload lost the upload. Aborting."
grep -q 'VideoInfoForm' "$TMPD/m12"              || die "UploadZone.tsx payload missing the details form. Aborting."
grep -q 'SHOW_PLANNED' "$TMPD/m11"               || die "AppShell.tsx payload lost the sidebar. Aborting."
grep -q 'createUpload' "$TMPD/m14"               || die "api.ts payload lost the upload calls. Aborting."
say "24 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied video details, visibility and library pages (rebuild Part 3b)."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit) && (cd frontend && npx tsc --noEmit && npm run build)"
say "Undo: ./vm_info.sh --revert"
